6	//  for the W+2jet process over the two helicity orientations of the
7	//  gluon pairs (k3,k4) and (k5,k6).
8	
9	#include "LRcalc.hpp"
10	#include <complex>
11	#include <mxpart_mod.hpp>
12	#include <sprods_com_mod.hpp>
13	
14	void LRcalc(int k1, int k2, int k3, int k4, int k5, int k6,
15	            FArray2D<std::complex<double>>& za,
16	            FArray2D<std::complex<double>>& zb,
17	            FArray1D<std::complex<double>>& A,
18	            FArray2D<std::complex<double>>& Xpp,
19	            FArray2D<std::complex<double>>& Xmp,
20	            FArray2D<std::complex<double>>& Xpm,
21	            FArray2D<std::complex<double>>& Xmm) {
22	  using namespace mxpart_mod;
23	  using namespace sprods_com_mod;
24	
25	  // Statement functions translated as lambdas
26	  auto zab2 = [&za, &zb](int i1, int i2, int i3, int i4) -> std::complex<double> {
27	    return za(i1,i2)*zb(i2,i4) + za(i1,i3)*zb(i3,i4);
28	  };
29	  auto zba2 = [&za, &zb](int i1, int i2, int i3, int i4) -> std::complex<double> {
30	    return zb(i1,i2)*za(i2,i4) + zb(i1,i3)*za(i3,i4);
31	  };
32	
33	  double s12 = s(k1,k2);
34	  double s34 = s(k3,k4);
35	  double s56 = s(k5,k6);
36	
37	  for (int h3 = 1; h3 <= 2; h3++) {
38	    int l3, l4;
39	    if (h3 == 1) {
40	      l3 = k3;
41	      l4 = k4;
42	    } else {
43	      l3 = k4;
44	      l4 = k3;
45	    }
46	    for (int h5 = 1; h5 <= 2; h5++) {
47	      int l5, l6;
48	      if (h5 == 1) {
49	        l5 = k5;
50	        l6 = k6;
51	      } else {
52	        l5 = k6;
53	        l6 = k5;
54	      }
55	
56	      Xmp(h3,h5) = (
57	          A(2)*s12*za(l3,l5)*zb(l4,l6)*zab2(k1,k3,k4,k2)/zab2(k2,k3,k4,k1)
58	        - (A(3)+A(4))*za(k1,l3)*za(k1,l5)*zb(k2,l4)*zb(k2,l6)
59	        + A(5)*zab2(k1,k3,k4,k2)
60	          *(za(l3,l5)*zb(k2,l4)*zb(l6,k2)/zb(k1,k2)
61	           +za(k1,l3)*za(k1,l5)*zb(l4,l6)/za(k1,k2))
62	      ) / s34 / s56 / s12;
63	
64	      Xpp(h3,h5) = za(l3,l5)/(za(k1,k2)*s12*s34*s56)*(
65	          (A(3)+A(1))*s12*zb(k1,l6)*zb(l4,k2)
66	        - (A(4)+A(1))*s12*zb(k2,l6)*zb(l4,k1)
67	        + A(5)*(zb(k2,l4)*zb(k2,l6)*zab2(k2,k3,k4,k1)
68	               -zb(k1,l4)*zb(k1,l6)*zab2(k1,k3,k4,k2))
69	      );
70	
71	      Xpm(3-h3,3-h5) = (
72	          A(2)*s12*zb(l3,l5)*za(l4,l6)*zba2(k1,k3,k4,k2)/zba2(k2,k3,k4,k1)
73	        - (A(3)+A(4))*zb(k1,l3)*zb(k1,l5)*za(k2,l4)*za(k2,l6)
74	        + A(5)*zba2(k1,k3,k4,k2)
75	          *(zb(l3,l5)*za(k2,l4)*za(l6,k2)/za(k1,k2)
76	           +zb(k1,l3)*zb(k1,l5)*za(l4,l6)/zb(k1,k2))
77	      ) / s34 / s56 / s12;
78	
79	      Xmm(3-h3,3-h5) = zb(l3,l5)/(zb(k1,k2)*s12*s34*s56)*( // @coverage-probe
80	          (A(3)+A(1))*s12*za(k1,l6)*za(l4,k2)
81	        - (A(4)+A(1))*s12*za(k2,l6)*za(l4,k1)
82	        + A(5)*(za(k2,l4)*za(k2,l6)*zba2(k2,k3,k4,k1)
83	               -za(k1,l4)*za(k1,l6)*zba2(k1,k3,k4,k2))
84	      );
85	    }
86	  }
87	}
