89	extern "C" {
90	  void LRcalc_wrapper(int k1, int k2, int k3, int k4, int k5, int k6,
91	                      std::complex<double>* fza, std::complex<double>* fzb,
92	                      std::complex<double>* fA,
93	                      std::complex<double>* fXpp, std::complex<double>* fXmp,
94	                      std::complex<double>* fXpm, std::complex<double>* fXmm) {
95	    using namespace mxpart_mod;
96	    FArray2D<std::complex<double>> za(fza, mxpart, mxpart);
97	    FArray2D<std::complex<double>> zb(fzb, mxpart, mxpart);
98	    FArray1D<std::complex<double>> A(fA, 6);
99	    FArray2D<std::complex<double>> Xpp(fXpp, 2, 2);
100	    FArray2D<std::complex<double>> Xmp(fXmp, 2, 2);
101	    FArray2D<std::complex<double>> Xpm(fXpm, 2, 2);
